import{_ as a,C as d,o as n,c as r,j as e,a as s,E as i,a3 as c}from"./chunks/framework.DEy3KOfk.js";const b=JSON.parse('{"title":"Waypoints","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/waypoints/README.md"},"headers":[],"relativePath":"packages/waypoints/README.md","filePath":"packages/waypoints/README.md","lastUpdated":1791534325000}'),p={name:"packages/waypoints/README.md"},l={id:"waypoints",tabindex:"-1",class:"component-page-title"},m={class:"component-page-title__version",href:"https://github.com/filiphsps/pumpkin-plugins/releases/tag/waypoints-v0.0.1","aria-label":"Release v0.0.1"};function h(y,t,g,u,w,v){const o=d("Badge");return n(),r("div",null,[e("h1",l,[t[0]||(t[0]=e("span",{class:"component-page-title__text"},[s("Waypoints "),e("a",{class:"header-anchor",href:"#waypoints","aria-label":'Permalink to "Waypoints"'},"​")],-1)),e("a",m,[i(o,{type:"info",text:"v0.0.1"})])]),t[1]||(t[1]=c('<p>Server-managed waypoints with access rules, a Java HUD (bedrock coming later), and vanilla commands</p><p>See the <a href="https://filiphsps.github.io/pumpkin-plugins/packages/waypoints/docs/" target="_blank" rel="noreferrer">plugin guide</a> and <a href="https://filiphsps.github.io/pumpkin-plugins/api/plugins/waypoints/" target="_blank" rel="noreferrer">API reference</a> on the documentation site.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Put <code>waypoints.wasm</code> from the plugin&#39;s GitHub release in your server&#39;s <code>plugins/</code> folder and restart. Hot reload cannot ask for permissions, so the first load needs a restart.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Pumpkin asks for these on the server console the first time the plugin loads.</p><table tabindex="0"><thead><tr><th>Permission</th><th>Why</th></tr></thead><tbody><tr><td><code>fs.read.data</code></td><td>Read the waypoint store from the plugin data folder.</td></tr><tr><td><code>fs.write.data</code></td><td>Persist waypoint changes in the plugin data folder.</td></tr><tr><td><code>http.outbound</code></td><td>Check Pumpkin Market for plugin updates.</td></tr></tbody></table><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th><th>Permission</th><th>Default access</th></tr></thead><tbody><tr><td><code>/wp create</code></td><td>Create a waypoint at your position or explicit coordinates</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp create &lt;name&gt;</code></td><td>Create a waypoint at your position or explicit coordinates</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp create &lt;name&gt; &lt;x&gt; &lt;y&gt; &lt;z&gt;</code></td><td>Create a waypoint at your position or explicit coordinates</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp reload</code></td><td>Reload waypoint data from disk</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp delete &lt;name&gt;</code></td><td>Delete a waypoint by name</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp rename &lt;name&gt; &lt;newName&gt;</code></td><td>Rename a waypoint</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp relocate</code></td><td>Move a waypoint to your position or explicit coordinates</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp relocate &lt;name&gt;</code></td><td>Move a waypoint to your position or explicit coordinates</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp relocate &lt;name&gt; &lt;x&gt; &lt;y&gt; &lt;z&gt;</code></td><td>Move a waypoint to your position or explicit coordinates</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp list</code></td><td>List enabled waypoints you can access</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp info &lt;name&gt;</code></td><td>Show details for an enabled waypoint you can access</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp teleport</code></td><td>Teleport to a waypoint or, as an operator, teleport selected players</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp teleport &lt;name&gt;</code></td><td>Teleport to a waypoint or, as an operator, teleport selected players</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp teleport &lt;name&gt; &lt;targets&gt;</code></td><td>Teleport to a waypoint or, as an operator, teleport selected players</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp tp</code></td><td>Alias for teleport</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp tp &lt;name&gt;</code></td><td>Alias for teleport</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp tp &lt;name&gt; &lt;targets&gt;</code></td><td>Alias for teleport</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp enable &lt;name&gt;</code></td><td>Enable a waypoint</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp disable &lt;name&gt;</code></td><td>Disable a waypoint</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp get &lt;name&gt;</code></td><td>Inspect a waypoint, including disabled records</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access public &lt;name&gt;</code></td><td>Allow every player to access a waypoint</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access restricted &lt;name&gt;</code></td><td>Restrict a waypoint to its grants</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access list &lt;name&gt;</code></td><td>List a waypoint access mode and its grants</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access grant player &lt;name&gt; &lt;player&gt;</code></td><td>Grant access to an online player</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access grant permission &lt;name&gt; &lt;permission&gt;</code></td><td>Grant access to a permission node</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access grant group &lt;name&gt; &lt;group&gt;</code></td><td>Grant access to a permission marker group</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access revoke player &lt;name&gt; &lt;player&gt;</code></td><td>Revoke an online player grant</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access revoke permission &lt;name&gt; &lt;permission&gt;</code></td><td>Revoke a permission node grant</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access revoke group &lt;name&gt; &lt;group&gt;</code></td><td>Revoke a permission marker group grant</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp set color &lt;name&gt; &lt;hex&gt;</code></td><td>Set the waypoint color</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp set icon &lt;name&gt; &lt;item&gt;</code></td><td>Set the waypoint item icon</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp set label &lt;name&gt; &lt;label&gt;</code></td><td>Set the waypoint display label</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp set description &lt;name&gt; &lt;description&gt;</code></td><td>Set the waypoint description</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp set visibility-range &lt;name&gt; &lt;range&gt;</code></td><td>Set the waypoint rendering range in blocks</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp reset &lt;name&gt; &lt;property&gt;</code></td><td>Reset one mutable waypoint property to its default</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr></tbody></table><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>This plugin has no configuration file.</p><h2 id="create-and-use-waypoints" tabindex="-1">Create and use waypoints <a class="header-anchor" href="#create-and-use-waypoints" aria-label="Permalink to &quot;Create and use waypoints&quot;">​</a></h2><p>Operators can create a waypoint at their exact position with <code>/wp create &quot;Home Base&quot;</code>, or provide absolute coordinates with <code>/wp create &quot;Home Base&quot; 120.5 64 -30</code>. Names are unique across worlds. Use <code>/wp list</code> to see enabled waypoints you can access, <code>/wp info &lt;name&gt;</code> for details, and <code>/wp tp &lt;name&gt;</code> to teleport yourself. Operators can use <code>/wp tp &lt;name&gt; @a</code> to teleport a player selector.</p><p>Only server operators can create, edit, enable, disable, grant, or delete waypoints. Administrative handlers check Pumpkin&#39;s operator list even if a command permission was manually granted. Player grants resolve online names and store UUIDs. Group grants check the permission marker <code>Waypoints:group.&lt;slug&gt;</code>; another permission provider must assign that marker to group members.</p><p>The versioned store is <code>plugins/data/Waypoints/waypoints.json</code>. If it is malformed or has an unsupported schema, the plugin preserves it and refuses writes until the issue is corrected. A successful v1 migration keeps the original bytes in <code>waypoints.v1.json</code>.</p><h2 id="java-waypoint-hud" tabindex="-1">Java waypoint HUD <a class="header-anchor" href="#java-waypoint-hud" aria-label="Permalink to &quot;Java waypoint HUD&quot;">​</a></h2><p>Minecraft Java 26.3 players see each enabled waypoint they can access in the same dimension and within its optional visibility range. Private display packets keep restricted names and personalized distances off other clients. Names reveal after a settled look and stay visible near the destination; distant peripheral markers show just their distance and icon. Labels use the waypoint color, a shadow, and a subtle backdrop independent of world lighting. Iconless waypoints use a colored diamond.</p><p>The HUD uses client-only TextDisplay entities along each waypoint&#39;s world direction. A smooth depth curve approaches a maximum of 24 blocks from the player&#39;s eyes, reducing the apparent movement caused by delayed position samples. Labels face the viewer and render through terrain. Camera rotation does not move or replace them. Between sixteen and three blocks from a waypoint, the projection blends into a world anchor two blocks above its stored Y coordinate. It never passes the destination during the blend; within three blocks it stays at the anchor. The transition works in both directions.</p><p>Perspective sizing uses camera-forward depth to avoid enlarging labels at the screen edges, and keeps their apparent size consistent through the approach at a fixed field of view. Labels are limited to 32 characters on the HUD; <code>/wp info</code> retains the complete text. Distances use meters below one kilometer and tenths of kilometers above it, with hysteresis to prevent rounding flicker. Text, icons, and backdrop fade between two and 0.75 blocks from the destination, leaving the immediate view clear.</p><p>Waypoints stored in the same half-block grid cell get a stable vertical stack, ordered by identifier, without camera-dependent rearrangement. Distinct waypoints along the same bearing may still overlap. Steps and jumps receive strong elevation damping while steep vertical destinations respond faster. Damping eases off near the world anchor. Position and scale updates interpolate over one client tick; unchanged text is not resent for appearance-only updates.</p><p>This approximates a first-person HUD: network latency, client view bobbing, and third-person camera offsets can still affect alignment. The server cannot read client FOV or reliably detect Java item-use state, so spyglass and modded zoom enlarge the labels. Other Java protocol versions and Bedrock clients do not receive the HUD. Icons use vanilla 26.3 atlas textures; block items use a representative model texture, and custom item IDs require the corresponding <code>item/&lt;path&gt;</code> sprite in the client&#39;s resource pack.</p><p>See the <a href="./docs/hud-preview">preview setup and test checklist</a> for building and trying the current HUD.</p>',22))])}const k=a(p,[["render",h]]);export{b as __pageData,k as default};
